CREATE TABLE {prefix}_agent_revision (scope_id TEXT NOT NULL, id TEXT NOT NULL, generation BIGINT NOT NULL, data TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (scope_id, id, generation)); INSERT OR IGNORE INTO {prefix}_agent_revision (scope_id, id, generation, data) SELECT scope_id, id, generation, data FROM {prefix}_agent; CREATE TRIGGER {prefix}_agent_revision_insert AFTER INSERT ON {prefix}_agent BEGIN INSERT OR IGNORE INTO {prefix}_agent_revision (scope_id, id, generation, data) VALUES (NEW.scope_id, NEW.id, NEW.generation, NEW.data); END; CREATE TRIGGER {prefix}_agent_revision_update AFTER UPDATE ON {prefix}_agent BEGIN INSERT OR IGNORE INTO {prefix}_agent_revision (scope_id, id, generation, data) VALUES (NEW.scope_id, NEW.id, NEW.generation, NEW.data); END
